import Amplify, { Auth } from 'aws-amplify';
import { useEffect, useState } from 'react';

Amplify.configure({
  Auth: {
    identityPoolId: 'us-east-1:384176c9-fd3e-4d5e-8ae9-46670ee5e528',
    region: 'us-east-1',
    userPoolWebClientId: '63lbgpl9eo5fma09hod6k4if12',
    userPoolId: 'us-east-1_H57PntW6G',
  },
});

const useAuthentication: UseAuthentication = () => {
  const [isLoggedIn, changeIsLoggedIn] = useState(false);
  const [isLoading, changeIsLoading] = useState(false);

  const makeLoginCheck = () => {
    changeIsLoading(true);
    checkIfUserIsLoggedIn().then((res) => {
      changeIsLoggedIn(Boolean(res));
      changeIsLoading(false);
    });
  };

  useEffect(makeLoginCheck, []);

  return {
    isLoggedIn,
    isLoading,
    makeLoginCheck,
    submitLogOut: () => {
      changeIsLoading(true);
      Auth.signOut().then(() => {
        makeLoginCheck();
        changeIsLoading(false);
      });
    },
  };
};

export type UseAuthentication = () => UseAuthenticationResponse;

export interface UseAuthenticationResponse {
  isLoggedIn: boolean;
  isLoading: boolean;
  submitLogOut: () => void;
  makeLoginCheck: () => void;
}

const checkIfUserIsLoggedIn = async (): Promise<boolean> => {
  try {
    const session = await Auth.currentSession();
    return Boolean(session);
  } catch {
    return false;
  }
};

export default useAuthentication;

import {
  Authenticator as AuthenticatorComponent,
  Greetings,
  // @ts-ignore
} from 'aws-amplify-react';
import React, { useContext } from 'react';
import styled from 'styled-components';
import theme from '../config/theme';
import { buttonStyles } from './Button';
import { inputStyles } from './Input';
import { navigate } from 'gatsby';
import AuthContext from './AuthWrapper/context';

const authenticatorTheme = {
  signInButton: {
    backgroundColor: theme.secondColorMidDark,
    color: 'blue',
  },
  formSection: {
    padding: '0.5rem',
  },
};

const Authenticator = () => {
  const auth = useContext(AuthContext);
  const handleStateChange = (state: string) => {
    if (state === 'signedIn') {
      navigate(`/`);
    }
    auth.makeLoginCheck();
  };
  return (
    <AuthenticatorWrapper>
      <AuthenticatorComponent
        theme={authenticatorTheme}
        onStateChange={handleStateChange}
        hide={[Greetings]}
      />
    </AuthenticatorWrapper>
  );
};

export default Authenticator;

const AuthenticatorWrapper = styled.div`
  * {
    --input-color: ${theme.midGrey};
    --deepSquidInk: ${theme.midGrey};
    --amazonOrange: ${theme.secondColorMidDark};
    --color-primary: ${theme.secondColorMidDark};
    --color-primary-highlight: ${theme.secondColorLight};
    --lightAmazonOrange: ${theme.secondColorLight};
    --darkAmazonOrange: ${theme.secondColorDarkText};
    --button-background-color: ${theme.secondColorMidDark};
  }
  button {
    ${buttonStyles}
    background-color: ${theme.secondColorMidDark};
    padding: 0.8rem;
    &:focus, &:active {
      background-color: ${theme.secondColorDarkText}
    }
    &:disabled {
      background-color: ${theme.secondColorDarkText};
    }
  }
  a {
    color: ${theme.secondColorDarkText}
  }
  input {
    ${inputStyles}
  }
`;

import React from 'react';
import useAuthentication from '../../hooks/useAuthentication';
import AuthContext from './context';

const LoginWrapper = ({ children }: { children: any }) => {
  const auth = useAuthentication();
  return <AuthContext.Provider value={auth}>{children}</AuthContext.Provider>;
};

export default LoginWrapper;

import React from 'react';
import { UseAuthenticationResponse } from '../../hooks/useAuthentication';

const defaultContext: UseAuthenticationResponse = null;

const AuthContext = React.createContext(defaultContext);

export default AuthContext;

import React from 'react';
import Input from './Input';
import styled from 'styled-components';
import SearchIcon from '@material-ui/icons/Search';
import theme from '../config/theme';

const SearchInput = (props: any) => {
  return (
    <div style={{ position: 'relative' }}>
      <StyledInput {...props} />
      <SearchIconWrapper>
        <SearchIcon />
      </SearchIconWrapper>
    </div>
  );
};

const StyledInput = styled(Input)`
  padding-right: 2.2rem;
`;

const SearchIconWrapper = styled.div`
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  right: 0.5rem;
  svg {
    font-size: 1.5rem;
    color: ${theme.midLightGrey};
  }
`;

export default SearchInput;

import { graphql } from 'gatsby';
import React, { useState } from 'react';
import { connect } from 'react-redux';
import CellWithSubtitle from '../components/CellWithSubtitle';
import Description from '../components/Description';
import FloatingWhiteBox from '../components/FloatingWhiteBox';
import Header from '../components/Header';
import Padding from '../components/Padding';
import Pill from '../components/Pill';
import SearchInput from '../components/SearchInput';
import SubHeadingWithDivider from '../components/SubHeadingWithDivider';
import Table from '../components/Table';
import createAvailableAccentSubtitle from '../utils/createAvailableAccentSubtitle';
import { ReduxState } from '../utils/redux/redux';

const SearchPage = ({ data, navigate, practiceAccent }: Props) => {
  const [value, onChange] = useState('');
  return (
    <>
      <FloatingWhiteBox>
        <Header>Dictionary</Header>
        <Padding />
        <Description>Explore our library of accents, word by word.</Description>
        <Padding />
        <SearchInput
          value={value}
          onChange={(e: any) => onChange(e.target.value)}
          placeholder="Search words"
        />
        <Padding />
        <SubHeadingWithDivider>Results</SubHeadingWithDivider>
        <Padding />
        <Table
          data={data.words.edges
            .filter(({ node }) =>
              new RegExp(value.toLowerCase()).test(node.word),
            )
            .filter((_, index) => index < 10)
            .map((edge) => ({ ...edge, id: edge.node.id }))}
          schema={{
            renderCell: ({ node }) => (
              <CellWithSubtitle
                title={node.word}
                subtitle={createAvailableAccentSubtitle(node.availableAccents)}
                pills={
                  practiceAccent &&
                  node.availableAccents.includes(practiceAccent) && [
                    <Pill>Target Accent</Pill>,
                  ]
                }
              />
            ),
            onClick: ({ node }) => navigate(`/words/${node.word}`),
          }}
        />
      </FloatingWhiteBox>
    </>
  );
};

interface Props {
  navigate: (url: string) => void;
  practiceAccent: string;
  practiceSound: string;
  data: {
    words: {
      edges: {
        node: {
          id: string;
          word: string;
          availableAccents: string[];
        };
      }[];
    };
  };
}

export const SEARCH_QUERY = graphql`
  query allWordsQuery {
    words: allWordsYaml(
      filter: { availableAccents: { regex: "/([A-Z|a-z])/" } }
    ) {
      edges {
        node {
          id
          word
          availableAccents
        }
      }
    }
  }
`;

const mapStateToProps = (state: ReduxState) => ({
  practiceAccent: state.global.practiceAccent,
  practiceSound: state.global.practiceSound,
});

export default connect(mapStateToProps)(SearchPage);
